/* ===== LUXURY BOOKING PROGRESS BAR ===== */
.cv-progress-bar-wrap {
  width: 100%;
  background: linear-gradient(135deg, #0f6b8e 0%, #1a9e6b 50%, #76b84f 100%);
  padding: 16px 24px 14px;
  position: sticky;
  top: 0;
  z-index: 200;
  box-shadow: 0 4px 24px rgba(15,107,142,0.35);
  border-bottom: 1px solid rgba(255,255,255,0.18);
  display: none;
}
.cv-progress-bar-wrap.visible { display: block; }

.cv-progress-steps {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 0;
  max-width: 680px;
  margin: 0 auto;
}

.cv-step {
  display: flex;
  flex-direction: column;
  align-items: center;
  flex: 1;
  position: relative;
  cursor: default;
}

.cv-step-connector {
  flex: 1;
  height: 2px;
  background: rgba(255,255,255,0.25);
  margin: 0;
  margin-bottom: 20px;
  transition: background 0.4s ease;
}
.cv-step-connector.done {
  background: linear-gradient(90deg, #fff, rgba(255,255,255,0.8));
}

.cv-step-circle {
  width: 30px;
  height: 30px;
  border-radius: 50%;
  border: 2px solid rgba(255,255,255,0.4);
  background: rgba(255,255,255,0.12);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 11px;
  font-weight: 700;
  color: rgba(255,255,255,0.6);
  transition: all 0.4s cubic-bezier(0.4,0,0.2,1);
  letter-spacing: 0.02em;
  position: relative;
  z-index: 2;
}

.cv-step.done .cv-step-circle {
  border-color: #fff;
  background: rgba(255,255,255,0.22);
  color: #fff;
  box-shadow: 0 0 12px rgba(255,255,255,0.3);
}

.cv-step.active .cv-step-circle {
  border-color: #fff;
  background: #fff;
  color: #0f6b8e;
  box-shadow: 0 0 20px rgba(255,255,255,0.6), 0 0 40px rgba(255,255,255,0.2);
  transform: scale(1.12);
}

.cv-step-label {
  font-size: 9.5px;
  font-weight: 600;
  color: rgba(255,255,255,0.5);
  margin-top: 6px;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  text-align: center;
  white-space: nowrap;
  transition: color 0.4s ease;
  font-family: inherit;
}
.cv-step.done .cv-step-label { color: rgba(255,255,255,0.75); }
.cv-step.active .cv-step-label { color: #fff; font-weight: 700; }

.cv-step-check {
  display: none;
}
.cv-step.done .cv-step-check { display: inline; }
.cv-step.done .cv-step-num { display: none; }

/* RTL support */
body.rtl .cv-step-label { font-family: inherit; }

@media (max-width: 480px) {
  .cv-progress-bar-wrap { padding: 12px 12px 10px; }
  .cv-step-circle { width: 26px; height: 26px; font-size: 10px; }
  .cv-step-label { font-size: 8px; }
}
    


