.btn-urgent-hero:hover{background:linear-gradient(135deg,#84c95c,#4f9631)!important;color:#fff!important;box-shadow:0 18px 34px -14px rgba(118,184,79,0.75);transform:translateY(-2px) scale(1.02);}
body.dark-mode .btn-urgent-hero{background:linear-gradient(135deg,#8fcb5d,#6fb840)!important;color:#08131b!important;border-color:rgba(143,203,93,0.4);box-shadow:0 18px 34px -14px rgba(143,203,93,0.35);}
body.dark-mode .btn-urgent-hero:hover{background:linear-gradient(135deg,#a2d975,#79c24a)!important;color:#08131b!important;}
.urgent-booking-card h1{font-size:2rem;color:var(--accent-dark);margin-bottom:.6rem;}
.urgent-intro{font-size:1.04rem;margin-bottom:1rem;}
.urgent-chip{display:inline-flex;align-items:center;gap:.55rem;background:var(--accent-light);color:var(--accent-dark);padding:.55rem 1rem;border-radius:999px;font-weight:700;margin-bottom:1rem;}
.urgent-note{display:flex;align-items:flex-start;gap:.7rem;background:var(--bg-color);border:1px solid var(--border-color);border-radius:24px;padding:1rem 1.1rem;margin:1.1rem 0 1.7rem;}
.urgent-note i{margin-top:.18rem;color:var(--accent-contrast);}
.urgent-success-card{padding-top:.4rem;}
.urgent-summary-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:1rem;margin:1.4rem 0;}
.urgent-summary-item{background:var(--bg-color);border:1px solid var(--border-color);border-radius:24px;padding:1rem 1.1rem;text-align:center;}
.urgent-summary-item span{display:block;font-size:.92rem;opacity:.82;margin-bottom:.35rem;}
.urgent-summary-item strong{font-size:1.08rem;}
.split-form-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:1rem;}
.field-help-text{font-size:.92rem;opacity:.8;margin-top:.45rem;}
.file-upload-group input[type="file"]{padding:.8rem;}
.upload-file-name{font-size:.92rem;opacity:.82;margin-top:.45rem;word-break:break-word;}
.join-us-btn{display:inline-flex;align-items:center;justify-content:center;gap:.55rem;margin-top:.9rem;width:100%;}
.careers-card h1{font-size:2rem;color:var(--accent-dark);margin-bottom:.6rem;}
.careers-chip{background:rgba(118,184,79,0.16);color:var(--accent-dark);}
