.btn-secondary-soft{background:var(--bg-color)!important;color:var(--accent-dark)!important;border:1px solid var(--border-color);box-shadow:none;}
.btn-secondary-soft:hover{background:var(--accent-light)!important;color:var(--accent-dark)!important;box-shadow:none;}
