/* ══════════════════════════════════════════
   CAREVIA AUTH — REDESIGN v2
══════════════════════════════════════════ */
@keyframes cvFadeIn{from{opacity:0;transform:translateY(20px) scale(.97)}to{opacity:1;transform:translateY(0) scale(1)}}
@keyframes cvSlideUp{from{opacity:0;transform:translateY(10px)}to{opacity:1;transform:translateY(0)}}
@keyframes cvShake{0%,100%{transform:translateX(0)}20%,60%{transform:translateX(-6px)}40%,80%{transform:translateX(6px)}}

/* ── Overlay ── */
.cv-overlay{
  position:fixed;inset:0;
  background:rgba(7,22,32,0.55);
  backdrop-filter:blur(8px);
  -webkit-backdrop-filter:blur(8px);
  z-index:9000;display:flex;align-items:center;justify-content:center;padding:1rem;
}

/* ── Modal Card ── */
.cv-modal{
  background:var(--card-bg);
  border-radius:28px;
  padding:0;
  width:100%;max-width:420px;
  box-shadow:0 32px 80px -16px rgba(7,22,32,0.35), 0 0 0 1px rgba(255,255,255,0.08);
  position:relative;
  animation:cvFadeIn .32s cubic-bezier(.34,1.38,.64,1);
  overflow:hidden;
}

/* ── Modal Header Band ── */
.cv-modal-header{
  background:linear-gradient(135deg, var(--accent-dark) 0%, #0a7a9e 100%);
  padding:1.6rem 2rem 1.4rem;
  position:relative;
  overflow:hidden;
}
.cv-modal-header::before{
  content:'';
  position:absolute;top:-40px;right:-40px;
  width:130px;height:130px;
  border-radius:50%;
  background:rgba(255,255,255,0.07);
  pointer-events:none;
}
.cv-modal-header::after{
  content:'';
  position:absolute;bottom:-30px;left:-20px;
  width:90px;height:90px;
  border-radius:50%;
  background:rgba(118,184,79,0.18);
  pointer-events:none;
}
.cv-modal-header-icon{
  width:44px;height:44px;
  border-radius:14px;
  background:rgba(255,255,255,0.15);
  display:flex;align-items:center;justify-content:center;
  font-size:1.15rem;color:#fff;
  margin-bottom:.75rem;
  backdrop-filter:blur(4px);
}
.cv-modal h2{
  font-size:1.35rem;font-weight:800;
  color:#fff !important;
  margin:0;line-height:1.2;
  position:relative;z-index:1;
}
.cv-modal-subtitle{
  font-size:.82rem;color:rgba(255,255,255,0.72);
  margin:.3rem 0 0;position:relative;z-index:1;
}

/* ── Modal Body ── */
.cv-modal-body{padding:1.6rem 2rem 2rem;}

/* ── Form Groups ── */
.cv-modal .form-group{margin-bottom:1.1rem;animation:cvSlideUp .25s ease both;}
.cv-modal .form-group:nth-child(1){animation-delay:.05s}
.cv-modal .form-group:nth-child(2){animation-delay:.1s}
.cv-modal .form-group:nth-child(3){animation-delay:.15s}
.cv-modal .form-group:nth-child(4){animation-delay:.2s}
.cv-modal .form-group:nth-child(5){animation-delay:.25s}
.cv-modal .form-group:nth-child(6){animation-delay:.3s}

.cv-modal label{
  display:flex;align-items:center;gap:.4rem;
  font-size:.78rem;font-weight:700;letter-spacing:.04em;text-transform:uppercase;
  margin-bottom:.45rem;color:var(--text-color);opacity:.65;
}
.cv-modal label i{font-size:.75rem;opacity:.8;}

.cv-input-wrap{position:relative;}
.cv-modal input{
  width:100%;
  padding:.75rem 1rem .75rem 2.6rem;
  border:2px solid var(--border-color);
  border-radius:14px;
  background:var(--input-bg);
  color:var(--text-color);
  font-size:.95rem;
  outline:none;
  transition:border-color .2s, box-shadow .2s, transform .15s;
  font-family:inherit;
}
.cv-modal input:focus{
  border-color:var(--accent-dark);
  box-shadow:0 0 0 4px rgba(15,88,115,.12);
  transform:translateY(-1px);
}
.cv-modal input::placeholder{opacity:.38;font-size:.88rem;}
.cv-input-icon{
  position:absolute;left:.9rem;top:50%;transform:translateY(-50%);
  color:var(--accent-dark);opacity:.55;font-size:.85rem;
  pointer-events:none;
}
body.rtl .cv-modal input{padding:.75rem 2.6rem .75rem 1rem;}
body.rtl .cv-input-icon{left:auto;right:.9rem;}

/* ══════════════════════════════════
   REGISTER FORM — MULTI-STEP DESIGN
══════════════════════════════════ */
.cv-reg-header { padding-bottom: 0; }
.cv-reg-header-top {
  display: flex; align-items: center; gap: .85rem;
  margin-bottom: 1.2rem; position: relative; z-index: 1;
}
.cv-reg-icon-large {
  width: 52px !important; height: 52px !important;
  border-radius: 18px !important; font-size: 1.3rem !important;
  flex-shrink: 0; background: rgba(255,255,255,0.18) !important;
  backdrop-filter: blur(6px);
}
.cv-reg-steps {
  display: flex; align-items: center; justify-content: center;
  gap: 0; padding: 1rem 1.6rem 1.25rem;
  background: rgba(255,255,255,0.07);
  border-top: 1px solid rgba(255,255,255,0.12);
  margin: 0 -2rem;
}
.cv-reg-step {
  display: flex; flex-direction: column; align-items: center;
  gap: .35rem; flex: 0 0 auto; transition: opacity .3s; opacity: .45;
}
.cv-reg-step.active { opacity: 1; }
.cv-reg-step.done { opacity: .75; }
.cv-step-circle {
  width: 36px; height: 36px; border-radius: 50%;
  background: rgba(255,255,255,0.14);
  border: 2px solid rgba(255,255,255,0.22);
  display: flex; align-items: center; justify-content: center;
  font-size: .82rem; color: rgba(255,255,255,0.7);
  transition: all .3s ease;
}
.cv-reg-step.active .cv-step-circle {
  background: rgba(255,255,255,0.9); border-color: #fff;
  color: var(--accent-dark); box-shadow: 0 4px 14px rgba(0,0,0,0.2);
}
.cv-reg-step.done .cv-step-circle {
  background: rgba(118,184,79,0.4); border-color: rgba(118,184,79,0.7); color: #fff;
}
.cv-reg-step.done .cv-step-circle i { display: none; }
.cv-reg-step.done .cv-step-circle::before {
  content: '\f00c'; font-family: 'Font Awesome 6 Free';
  font-weight: 900; font-size: .78rem;
}
.cv-reg-step span { font-size: .7rem; font-weight: 700; color: rgba(255,255,255,0.7); white-space: nowrap; }
.cv-reg-step.active span { color: #fff; }
.cv-reg-step-line {
  flex: 1; height: 2px; background: rgba(255,255,255,0.18);
  margin: 0 .4rem; margin-bottom: 1.2rem;
  border-radius: 2px; min-width: 28px; transition: background .3s;
}
.cv-reg-step-line.done { background: rgba(118,184,79,0.5); }
.cv-reg-body { padding-top: 1.4rem; }
.cv-reg-panel-hint {
  display: flex; align-items: center; gap: .5rem;
  font-size: .82rem; color: var(--accent-dark);
  background: linear-gradient(135deg, rgba(15,88,115,0.07), rgba(118,184,79,0.08));
  border: 1px solid rgba(15,88,115,0.1);
  border-radius: 12px; padding: .65rem .9rem;
  margin-bottom: 1.1rem; font-weight: 600;
}
.cv-reg-panel-hint i { opacity: .8; }
.cv-reg-two-col { display: grid; grid-template-columns: 1fr 1fr; gap: .75rem; }
@media (max-width: 480px) { .cv-reg-two-col { grid-template-columns: 1fr; } }
.cv-reg-panel { animation: cvSlideUp .28s ease both; }
.cv-reg-next-btn {
  width: 100%; margin-top: .7rem;
  display: flex; align-items: center; justify-content: center;
  gap: .55rem;
}
.cv-reg-back-btn {
  width: 100%; margin-top: .65rem; padding: .62rem;
  background: none; border: 1.5px solid var(--border-color);
  border-radius: 12px; color: var(--text-color);
  font-size: .86rem; font-weight: 700; cursor: pointer;
  display: flex; align-items: center; justify-content: center;
  gap: .45rem; opacity: .65; transition: opacity .2s, border-color .2s;
}
.cv-reg-back-btn:hover { opacity: 1; border-color: var(--accent-dark); color: var(--accent-dark); }
.cv-code-box {
  background: linear-gradient(135deg, rgba(15,88,115,0.05), rgba(118,184,79,0.06));
  border: 1.5px dashed rgba(15,88,115,0.2);
  border-radius: 16px; padding: 1rem;
  animation: cvSlideUp .25s ease both;
}
.cv-pw-strength { display: flex; align-items: center; gap: .7rem; margin: .4rem 0 .1rem; }
.cv-pw-bar { flex: 1; height: 5px; background: var(--border-color); border-radius: 99px; overflow: hidden; }
.cv-pw-fill { height: 100%; border-radius: 99px; width: 0%; transition: width .35s ease, background .35s ease; }
.cv-pw-label { font-size: .74rem; font-weight: 700; min-width: 52px; text-align: end; }

/* Date input special */
input[type="date"].cv-date{padding:.7rem 1rem;}
body.rtl input[type="date"].cv-date{padding:.7rem 1rem;}

/* ── Primary Button ── */
.cv-modal .cv-btn-primary{
  width:100%;
  padding:.9rem 1rem;
  border:none;
  border-radius:14px;
  background:linear-gradient(135deg, var(--accent-dark) 0%, #0a8ab0 100%);
  color:#fff;
  font-size:1rem;font-weight:800;letter-spacing:.01em;
  cursor:pointer;
  margin-top:.4rem;
  transition:all .25s;
  display:flex;align-items:center;justify-content:center;gap:.5rem;
  box-shadow:0 8px 20px -8px rgba(15,88,115,.55);
}
.cv-modal .cv-btn-primary:hover{
  background:linear-gradient(135deg,#0a8ab0 0%, var(--accent-contrast) 100%);
  box-shadow:0 12px 28px -8px rgba(15,88,115,.5);
  transform:translateY(-2px);
}
.cv-modal .cv-btn-primary:active{transform:translateY(0);}

/* Slightly smaller login button for better proportion */
#cvLoginBtn{
  padding:.78rem 1rem;
  font-size:.95rem;
  border-radius:13px;
  gap:.42rem;
  min-height:46px;
}

/* ── Switch Link ── */
.cv-modal .cv-switch{
  text-align:center;margin-top:1.1rem;
  font-size:.86rem;color:var(--text-color);opacity:.7;
}
.cv-modal .cv-switch span{
  color:var(--accent-dark);cursor:pointer;font-weight:700;
  text-decoration:underline;text-underline-offset:3px;
  transition:opacity .15s;
}
.cv-modal .cv-switch span:hover{opacity:.7;}

/* ── Close Button ── */
.cv-modal .cv-close{
  position:absolute;top:.9rem;right:.9rem;
  width:32px;height:32px;
  background:rgba(255,255,255,0.18);
  border:none;border-radius:50%;
  font-size:.95rem;
  cursor:pointer;
  color:#fff;
  display:flex;align-items:center;justify-content:center;
  line-height:1;
  transition:background .2s, transform .2s;
  z-index:10;
}
.cv-modal .cv-close:hover{background:rgba(255,255,255,0.3);transform:scale(1.1);}

/* ── Error Message ── */
.cv-err{
  color:#e53e3e;font-size:.82rem;margin-top:.4rem;
  display:none;
  padding:.5rem .75rem;
  background:rgba(229,62,62,.08);
  border-radius:8px;
  border-left:3px solid #e53e3e;
}
.cv-err.show{display:block;animation:cvShake .35s ease;}

.cv-inline-actions{
  display:flex;
  gap:.65rem;
  align-items:center;
  margin-top:.7rem;
}
.cv-inline-actions .cv-btn-secondary,
.cv-btn-secondary{
  flex:0 0 auto;
  min-width:138px;
  padding:.78rem 1rem;
  border-radius:12px;
  border:1.5px solid rgba(15,88,115,.16);
  background:linear-gradient(180deg, rgba(255,255,255,.98), rgba(240,248,244,.98));
  color:var(--accent-dark);
  font-weight:800;
  cursor:pointer;
  transition:all .22s ease;
}
.cv-inline-actions .cv-btn-secondary:hover,
.cv-btn-secondary:hover{
  transform:translateY(-1px);
  border-color:rgba(15,88,115,.28);
  box-shadow:0 10px 24px -18px rgba(15,88,115,.45);
}
body.dark-mode .cv-inline-actions .cv-btn-secondary,
body.dark-mode .cv-btn-secondary{
  background:linear-gradient(180deg, rgba(15,34,48,.96), rgba(12,28,39,.96));
  color:var(--text-color);
  border-color:rgba(102,182,207,.18);
}
.cv-verify-status{
  margin-top:.55rem;
  font-size:.82rem;
  padding:.58rem .75rem;
  border-radius:10px;
  display:none;
}
.cv-verify-status.show{display:block;}
.cv-verify-status.info{background:rgba(15,88,115,.08);color:var(--accent-dark);}
.cv-verify-status.success{background:rgba(118,184,79,.12);color:#2f6f1d;}
.cv-verify-status.error{background:rgba(229,62,62,.08);color:#c53030;}
.cv-verify-status i{margin-inline-end:.38rem;}
@media (max-width:640px){
  .cv-inline-actions{flex-direction:column;align-items:stretch;}
  .cv-inline-actions .cv-btn-secondary{width:100%;min-width:0;}
}


/* ════════════════════════════════
   NAVBAR AUTH BUTTON — REFINED
════════════════════════════════ */
/* ══ PHOTO UPLOAD ══ */
.cv-photo-upload-card{ overflow:visible!important; }
.cv-photo-upload-row{
  display:flex;align-items:center;gap:1rem;
  margin-top:.55rem;
}
.cv-photo-thumb{
  width:72px;height:72px;flex-shrink:0;
  border-radius:18px;
  background:#e8f4f8;
  border:2px solid rgba(15,88,115,.12);
  display:flex;align-items:center;justify-content:center;
  overflow:hidden;
  color:rgba(15,88,115,.35);font-size:1.6rem;
  transition:border-color .2s;
  box-shadow:0 2px 10px rgba(15,88,115,.1);
  isolation:isolate;
  position:relative;
  z-index:0;
}
.cv-photo-thumb img{
  position:absolute;inset:0;
  width:100%;height:100%;
  object-fit:cover;
  object-position:center;
  display:block;
  z-index:1;
  background:#e8f4f8;
}
body.dark-mode .cv-photo-thumb{ background:#0d2535; }
.cv-photo-upload-actions{
  display:flex;flex-direction:column;gap:.45rem;min-width:0;
}
.cv-upload-btn{
  display:inline-flex;align-items:center;gap:.45rem;
  padding:.52rem 1.1rem;
  border-radius:12px;
  background:#fff;
  color:#0b3d54;
  font-size:.82rem;font-weight:800;letter-spacing:.01em;
  cursor:pointer;
  border:1.5px solid rgba(15,88,115,.2);
  box-shadow:0 2px 8px rgba(15,88,115,.12);
  transition:all .22s cubic-bezier(.34,1.56,.64,1);
  user-select:none;width:fit-content;
}
.cv-upload-btn:hover{
  transform:translateY(-2px);
  border-color:rgba(15,88,115,.4);
  box-shadow:0 6px 16px rgba(15,88,115,.2);
  background:#f0f8fc;
}
.cv-upload-btn i{ font-size:.8rem; color:#0f6b8e; }
body.dark-mode .cv-upload-btn{
  background:rgba(255,255,255,.1);
  color:#d8eef7;
  border-color:rgba(102,182,207,.25);
}
body.dark-mode .cv-upload-btn:hover{
  background:rgba(255,255,255,.18);
  border-color:rgba(102,182,207,.4);
}
body.dark-mode .cv-upload-btn i{ color:#5bc8e8; }
.cv-upload-hint{ font-size:.73rem;color:#8aabb8;line-height:1.4; }
body.dark-mode .cv-upload-hint{color:#5a8898;}

/* ══ PANEL ACTION BUTTONS ══ */
.cv-panel-save-btn,
.cv-panel-reset-btn{
  display:flex;align-items:center;justify-content:center;gap:.6rem;
  border:none;cursor:pointer;font-weight:800;font-size:.88rem;
  border-radius:18px;min-height:54px;padding:.6rem 1rem;
  transition:all .26s cubic-bezier(.34,1.56,.64,1);
  position:relative;overflow:hidden;white-space:nowrap;width:100%;
}
.cv-panel-save-btn::after,.cv-panel-reset-btn::after{
  content:'';position:absolute;inset:0;
  background:linear-gradient(105deg,transparent 30%,rgba(255,255,255,.18) 50%,transparent 70%);
  transform:translateX(-100%);transition:transform .5s ease;pointer-events:none;
}
.cv-panel-save-btn:hover::after,.cv-panel-reset-btn:hover::after{ transform:translateX(100%); }
.cv-panel-save-btn{
  background:linear-gradient(135deg,#0f6b8e 0%,#094f6e 100%);
  color:#fff;
  box-shadow:0 6px 20px rgba(15,88,115,.35), 0 1px 0 rgba(255,255,255,.15) inset;
}
.cv-panel-save-btn:hover{ transform:translateY(-2px);box-shadow:0 10px 28px rgba(15,88,115,.5);filter:brightness(1.08); }
.cv-panel-save-btn:active{ transform:scale(.97); }
.cv-panel-save-icon{
  width:30px;height:30px;border-radius:9px;flex-shrink:0;
  display:flex;align-items:center;justify-content:center;
  background:rgba(255,255,255,.18);font-size:.85rem;
}
.cv-panel-reset-btn{
  background:linear-gradient(180deg,rgba(255,255,255,.98),rgba(240,248,244,.98));
  color:#0b3d54;border:1.5px solid rgba(15,88,115,.15);
  box-shadow:0 2px 10px rgba(15,88,115,.08);
}
.cv-panel-reset-btn:hover{ transform:translateY(-2px);border-color:rgba(15,88,115,.28);box-shadow:0 8px 22px rgba(15,88,115,.15); }
.cv-panel-reset-btn:active{ transform:scale(.97); }
.cv-panel-reset-icon{
  width:30px;height:30px;border-radius:9px;flex-shrink:0;
  display:flex;align-items:center;justify-content:center;
  background:linear-gradient(135deg,rgba(15,88,115,.1),rgba(118,184,79,.1));
  color:#0f6b8e;font-size:.82rem;
}
body.dark-mode .cv-panel-reset-btn{
  background:linear-gradient(180deg,rgba(10,26,38,.97),rgba(13,32,46,.97));
  color:#d8eef7;border-color:rgba(102,182,207,.18);
}
body.dark-mode .cv-panel-reset-icon{ color:#4ab8d8; }

/* ══ CHIP BUTTONS — MY BOOKINGS + LOGOUT ══ */

/* My Bookings */
.cv-user-chip .cv-dash-link{
  display:inline-flex;
  align-items:center;
  gap:.45rem;
  padding:.52rem 1rem;
  border:none;
  border-radius:999px;
  background:linear-gradient(135deg, #0f6b8e 0%, #094f6e 100%);
  color:#fff;
  font-size:.82rem;
  font-weight:800;
  letter-spacing:.01em;
  cursor:pointer;
  white-space:nowrap;
  position:relative;
  overflow:hidden;
  box-shadow:0 4px 14px rgba(15,88,115,.35);
  transition:all .25s cubic-bezier(.34,1.56,.64,1);
}
.cv-user-chip .cv-dash-link::before{
  content:'';
  position:absolute;inset:0;
  background:linear-gradient(105deg,transparent 30%,rgba(255,255,255,.2) 50%,transparent 70%);
  transform:translateX(-100%);
  transition:transform .5s ease;
  pointer-events:none;
}
