/* ══ SIGN IN BTN — PREMIUM ══ */
.cv-auth-btn{
  position:relative;
  display:inline-flex;
  align-items:center;
  gap:.62rem;
  padding:.52rem 1.2rem .52rem .52rem;
  border-radius:999px;
  border:1.5px solid transparent;
  background:
    linear-gradient(white, white) padding-box,
    linear-gradient(135deg, #0f6b8e, #76b84f) border-box;
  cursor:pointer;
  white-space:nowrap;
  box-shadow:
    0 2px 12px rgba(15,88,115,.13),
