  pointer-events:none;
}
.cv-auth-btn:hover{ transform:translateY(-2px); box-shadow:0 8px 24px rgba(15,88,115,.2), 0 2px 6px rgba(0,0,0,.08); }
.cv-auth-btn:hover::after{ opacity:1; }
.cv-auth-btn:active{ transform:scale(.97); }
body.dark-mode .cv-auth-btn{
  background:
    linear-gradient(rgba(12,30,44,.96), rgba(12,30,44,.96)) padding-box,
    linear-gradient(135deg, #0f6b8e, #76b84f) border-box;
  box-shadow:0 2px 12px rgba(0,0,0,.4);
}

/* Avatar circle */
.cv-auth-btn .cv-auth-icon{
  width:36px;height:36px;flex-shrink:0;
  border-radius:50%;
  display:inline-flex;align-items:center;justify-content:center;
  background:linear-gradient(135deg, #0f6b8e 0%, #76b84f 100%);
  color:#fff;
  box-shadow:0 3px 10px rgba(15,88,115,.35);
  transition:transform .26s cubic-bezier(.34,1.56,.64,1), box-shadow .26s ease;
  position:relative;z-index:1;
}
.cv-auth-btn:hover .cv-auth-icon{
  transform:scale(1.1) rotate(-5deg);
  box-shadow:0 5px 14px rgba(15,88,115,.5);
}
.cv-auth-btn .cv-auth-icon i{ font-size:.88rem; }

/* Label */
.cv-auth-btn .cv-auth-label{
  font-size:.88rem;font-weight:800;letter-spacing:.005em;
  color:#0b3d54;
  line-height:1;
  position:relative;z-index:1;
}
body.dark-mode .cv-auth-btn .cv-auth-label{ color:#d8eef7; }

/* Password visibility */
.cv-input-wrap{position:relative;}
.cv-password-toggle{
  position:absolute;
  right:.8rem;
  top:50%;
  transform:translateY(-50%);
  width:34px;
  height:34px;
  border:none;
  border-radius:50%;
  background:transparent;
  color:var(--accent-dark);
