.cv-password-toggle:hover{opacity:1;background:rgba(15,88,115,.08);}
.cv-password-toggle:active{transform:translateY(-50%) scale(.96);}
.cv-input-wrap.has-toggle input{padding-right:3rem;}
body.rtl .cv-password-toggle{right:auto;left:.8rem;}
body.rtl .cv-input-wrap.has-toggle input{padding-right:1rem;padding-left:3rem;}

/* User Chip */
/* ══════════════════════════════════
   ACCOUNT CHIP — LUXURY EDITION
══════════════════════════════════ */

/* Container */
.cv-user-chip{
  display:inline-flex;
  align-items:center;
  gap:0;
  padding:0;
  border-radius:24px;
  border:1px solid rgba(118,184,79,.25);
  overflow:hidden;
  position:relative;
  background:
    linear-gradient(145deg,
      rgba(15,88,115,.06) 0%,
      rgba(255,255,255,.96) 40%,
      rgba(118,184,79,.05) 100%);
  box-shadow:
    0 0 0 1px rgba(255,255,255,.8) inset,
    0 6px 24px rgba(15,88,115,.12),
    0 2px 6px rgba(0,0,0,.06);
  backdrop-filter:blur(24px) saturate(2);
  -webkit-backdrop-filter:blur(24px) saturate(2);
  transition:
    transform .3s cubic-bezier(.34,1.56,.64,1),
    box-shadow .3s ease,
    border-color .3s ease;
}
.cv-user-chip:hover{
  transform:translateY(-2px) scale(1.01);
  border-color:rgba(118,184,79,.4);
  box-shadow:
    0 0 0 1px rgba(255,255,255,.9) inset,
    0 12px 36px rgba(15,88,115,.18),
    0 4px 10px rgba(0,0,0,.08);
}
body.dark-mode .cv-user-chip{
  background:linear-gradient(145deg,rgba(8,26,36,.95),rgba(10,34,48,.92),rgba(7,28,20,.95));
  border-color:rgba(118,184,79,.18);
  box-shadow:0 0 0 1px rgba(255,255,255,.06) inset, 0 6px 24px rgba(0,0,0,.5);
}
body.dark-mode .cv-user-chip:hover{
  border-color:rgba(118,184,79,.32);
  box-shadow:0 0 0 1px rgba(255,255,255,.08) inset, 0 12px 36px rgba(0,0,0,.65);
}

/* Decorative gold line top */
.cv-user-chip::before{
  content:'';
  position:absolute;inset:0;bottom:auto;height:1.5px;
  background:linear-gradient(90deg,
    transparent 0%,
    rgba(118,184,79,.6) 30%,
    rgba(15,107,142,.7) 70%,
    transparent 100%);
  pointer-events:none;z-index:2;
}

/* ── AVATAR SECTION ── */
.cv-user-chip .cv-user-profile{
  display:flex;align-items:center;gap:.7rem;
  padding:.55rem .8rem .55rem .65rem;
  border-right:1px solid rgba(15,88,115,.08);
  min-width:0;
  position:relative;
}
body.dark-mode .cv-user-chip .cv-user-profile{
  border-right-color:rgba(255,255,255,.07);
}

/* Avatar circle */
.cv-user-chip .cv-user-avatar{
  position:relative;
  width:40px;height:40px;flex-shrink:0;
  border-radius:50%;
  background:
    radial-gradient(circle at 35% 35%, rgba(255,255,255,.3), transparent 55%),
    linear-gradient(145deg, #0f6b8e 0%, #0b4a63 50%, #3a8a2e 100%);
  display:flex;align-items:center;justify-content:center;
  color:#fff;font-size:.88rem;font-weight:900;letter-spacing:.02em;
  text-shadow:0 1px 3px rgba(0,0,0,.3);
  box-shadow:
    0 0 0 2.5px rgba(255,255,255,.9),
    0 0 0 4px rgba(118,184,79,.35),
    0 6px 16px rgba(15,88,115,.4);
  transition:
    transform .3s cubic-bezier(.34,1.56,.64,1),
    box-shadow .3s ease;
  overflow:hidden;
}
.cv-user-chip .cv-user-avatar img{
  width:100%;height:100%;
  object-fit:cover;
  display:block;
  border-radius:50%;
}
.cv-user-chip:hover .cv-user-avatar{
  transform:scale(1.08);
  box-shadow:
    0 0 0 2.5px rgba(255,255,255,.95),
    0 0 0 4.5px rgba(118,184,79,.5),
    0 8px 22px rgba(15,88,115,.55);
}
body.dark-mode .cv-user-chip .cv-user-avatar{
  box-shadow:
    0 0 0 2px rgba(255,255,255,.15),
    0 0 0 4px rgba(118,184,79,.25),
    0 6px 16px rgba(0,0,0,.5);
}

/* Status dot */
.cv-user-chip .cv-user-avatar::after{
  content:'';
  position:absolute;bottom:1px;right:1px;
  width:10px;height:10px;border-radius:50%;
  background:radial-gradient(circle at 35% 35%, #7de88a, #2db846);
  border:2.5px solid #fff;
  box-shadow:0 0 8px rgba(45,184,70,.7);
  animation:cvStatusPulse 2.8s ease-in-out infinite;
}
@keyframes cvStatusPulse{
  0%,100%{ box-shadow:0 0 4px rgba(45,184,70,.6); }
  50%{ box-shadow:0 0 12px rgba(45,184,70,.9), 0 0 22px rgba(45,184,70,.3); }
}
body.dark-mode .cv-user-chip .cv-user-avatar::after{border-color:#081a24;}

/* Text */
.cv-user-chip .cv-user-meta{display:flex;flex-direction:column;gap:.06rem;min-width:0;}
.cv-user-chip .cv-user-label{
  font-size:.56rem;font-weight:900;letter-spacing:.14em;text-transform:uppercase;
  color:var(--accent-contrast);
  opacity:.85;line-height:1;
}
body.dark-mode .cv-user-chip .cv-user-label{color:#7acc54;opacity:.9;}
.cv-user-chip .cv-user-name{
  font-size:.88rem;font-weight:800;
  color:var(--accent-dark);
  max-width:112px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;
  line-height:1.25;letter-spacing:-.01em;
}
body.dark-mode .cv-user-chip .cv-user-name{color:#e2f4fb;}


/* ════════════════════════════════
   BOOKING MODE MODAL — REDESIGN
════════════════════════════════ */
/* ══════════════════════════════════════
   BOOKING MODE MODAL — PREMIUM REDESIGN
══════════════════════════════════════ */
/* ══════════════════════════════════
   BOOKING MODE MODAL — PREMIUM V2
══════════════════════════════════ */
.cv-mode-modal{
  max-width:420px;
  width:calc(100% - 2rem);
  border-radius:32px;
  padding:0;
  overflow:hidden;
  background:#fff;
  border:none;
  box-shadow:
    0 0 0 1px rgba(15,88,115,.07),
    0 32px 80px -12px rgba(7,22,32,.32),
    0 8px 24px -4px rgba(15,88,115,.16);
  animation: cvModeIn .35s cubic-bezier(.22,1,.36,1) both;
}
@keyframes cvModeIn{
  from{ opacity:0; transform:translateY(18px) scale(.97); }
  to{ opacity:1; transform:none; }
}
body.dark-mode .cv-mode-modal{
  background:#0d1d29;
  box-shadow:0 32px 80px -12px rgba(0,0,0,.65), 0 0 0 1px rgba(255,255,255,.06);
}

/* ── Header ── */
.cv-mode-top{
  padding:2rem 1.75rem 1.5rem;
  display:block;
  position:relative;
  background:linear-gradient(145deg, #093d56 0%, #0f6b8e 55%, #158f72 100%);
  overflow:hidden;
}
.cv-mode-top::before{
  content:'';
  position:absolute; inset:0;
  background:
    radial-gradient(ellipse 90% 70% at 105% -15%, rgba(118,184,79,.5) 0%, transparent 55%),
    radial-gradient(ellipse 50% 60% at -5% 105%, rgba(255,255,255,.07) 0%, transparent 55%),
    url("data:image/svg+xml,%3Csvg width='60' height='60' viewBox='0 0 60 60' xmlns='http://www.w3.org/2000/svg'%3E%3Cg fill='none' fill-rule='evenodd'%3E%3Cg fill='%23ffffff' fill-opacity='0.03'%3E%3Ccircle cx='30' cy='30' r='20'/%3E%3C/g%3E%3C/g%3E%3C/svg%3E");
  pointer-events:none;
}
.cv-mode-top::after{
  content:'';
  position:absolute;
  bottom:-1px; left:0; right:0;
  height:28px;
  background:#fff;
  clip-path: ellipse(55% 100% at 50% 100%);
}
body.dark-mode .cv-mode-top::after{ background:#0d1d29; }
.cv-mode-top-inner{
  position:relative; z-index:1;
  display:flex; flex-direction:column; gap:.6rem;
}
/* logo pill */
.cv-mode-badge{
  display:inline-flex; align-items:center; gap:.35rem;
  width:max-content;
  padding:.28rem .7rem;
  border-radius:999px;
  background:rgba(255,255,255,.15);
  backdrop-filter:blur(10px);
  color:rgba(255,255,255,.92);
  font-size:.68rem; font-weight:700; letter-spacing:.08em; text-transform:uppercase;
  border:1px solid rgba(255,255,255,.2);
  margin-bottom:.2rem;
}
.cv-mode-modal h2{
  color:#fff !important;
  margin:0;
  font-size:1.55rem; font-weight:800; line-height:1.2; letter-spacing:-.025em;
}
.cv-mode-lead{
  margin:0;
  font-size:.83rem; color:rgba(255,255,255,.72); line-height:1.55;
}
/* ── Options ── */
.cv-mode-heading{ display:none; }
.cv-mode-options{
  display:flex; flex-direction:column; gap:.5rem;
  padding:1.25rem 1.25rem 1.4rem;
  background:#fff;
}
body.dark-mode .cv-mode-options{ background:#0d1d29; }

/* ── Cards ── */
.cv-mode-card{
  position:relative;
  border:1.5px solid #edf2f7;
  border-radius:20px;
  padding:1rem 1rem 1rem 1.05rem;
  cursor:pointer;
  transition:all .25s cubic-bezier(.34,1.56,.64,1);
  display:grid;
  grid-template-columns:56px 1fr 36px;
  align-items:center;
  gap:.85rem;
  background:#f8fbfe;
  overflow:hidden;
  text-align:left;
}
body.rtl .cv-mode-card{ text-align:right; }
body.dark-mode .cv-mode-card{
  background:rgba(255,255,255,.04);
  border-color:rgba(255,255,255,.07);
}

/* shimmer on hover */
.cv-mode-card::before{
  content:'';
  position:absolute; inset:0;
  background:linear-gradient(110deg, transparent 30%, rgba(255,255,255,.55) 50%, transparent 70%);
  transform:translateX(-100%);
  transition:transform .5s ease;
  border-radius:inherit;
  pointer-events:none; z-index:2;
}
.cv-mode-card:hover::before{ transform:translateX(100%); }

.cv-mode-card:hover{
  border-color:rgba(15,107,142,.28);
  transform:translateY(-3px) scale(1.01);
  box-shadow:0 14px 32px -8px rgba(15,88,115,.2), 0 4px 8px -2px rgba(15,88,115,.1);
  background:#fff;
}
body.dark-mode .cv-mode-card:hover{
  border-color:rgba(118,184,79,.28);
  background:rgba(255,255,255,.07);
  box-shadow:0 14px 32px -8px rgba(0,0,0,.45);
}
.cv-mode-card:active{ transform:scale(.985); transition-duration:.1s; }

/* — Card 1: Sign In — */
.cv-mode-card:nth-child(1){ border-left:3px solid #7c6cf5; }
.cv-mode-card:nth-child(1) .cv-mode-icon{
  background:linear-gradient(135deg, #ede9ff 0%, #cfe1f8 100%);
  box-shadow:0 4px 14px rgba(124,108,245,.25);
  color:#5b4fcf;
}
.cv-mode-card:nth-child(1) h3{ color:#3d2e99; }
body.rtl .cv-mode-card:nth-child(1){ border-left:none; border-right:3px solid #7c6cf5; }

/* — Card 2: Create Account — */
.cv-mode-card:nth-child(2){ border-left:3px solid #76b84f; }
.cv-mode-card:nth-child(2) .cv-mode-icon{
  background:linear-gradient(135deg, #f0fae6 0%, #d5f0c0 100%);
  box-shadow:0 4px 14px rgba(118,184,79,.28);
  color:#3d7a1f;
}
.cv-mode-card:nth-child(2) h3{ color:#2d5e14; }
body.rtl .cv-mode-card:nth-child(2){ border-left:none; border-right:3px solid #76b84f; }

/* — Card 3: Guest — */
.cv-mode-card:nth-child(3){ border-left:3px solid #0f9cda; }
.cv-mode-card:nth-child(3) .cv-mode-icon{
  background:linear-gradient(135deg, #dff3ff 0%, #c5e9f7 100%);
  box-shadow:0 4px 14px rgba(15,156,218,.22);
  color:#0670a0;
}
.cv-mode-card:nth-child(3) h3{ color:#054d74; }
body.rtl .cv-mode-card:nth-child(3){ border-left:none; border-right:3px solid #0f9cda; }

body.dark-mode .cv-mode-card h3{ color:#dceef7 !important; }
body.dark-mode .cv-mode-card:nth-child(1) .cv-mode-icon{ background:rgba(124,108,245,.18); }
body.dark-mode .cv-mode-card:nth-child(2) .cv-mode-icon{ background:rgba(118,184,79,.15); }
body.dark-mode .cv-mode-card:nth-child(3) .cv-mode-icon{ background:rgba(15,156,218,.15); }

/* Icon */
.cv-mode-card .cv-mode-icon{
  width:56px; height:56px; flex-shrink:0;
  border-radius:18px;
  display:flex; align-items:center; justify-content:center;
  font-size:1.5rem;
  position:relative; z-index:1;
}
/* Text */
.cv-mode-copy{ min-width:0; position:relative; z-index:1; }
.cv-mode-card h3{
  font-size:.95rem; font-weight:800; margin:0 0 .2rem; letter-spacing:-.01em;
}
.cv-mode-card p{
  font-size:.78rem; color:#6b8a9a; margin:0; line-height:1.45;
}
body.dark-mode .cv-mode-card p{ color:#6fa0b0; }

/* Arrow */
.cv-mode-arrow{
  width:36px; height:36px;
  border-radius:50%;
  display:flex; align-items:center; justify-content:center;
  background:#f0f5f9;
  color:#5a8a9f;
  font-size:.8rem; flex-shrink:0;
  transition:all .25s cubic-bezier(.34,1.56,.64,1);
  position:relative; z-index:1;
}
.cv-mode-card:hover .cv-mode-arrow{
  background:#0f6b8e; color:#fff;
  transform:translateX(4px);
  box-shadow:0 4px 12px rgba(15,88,115,.35);
}
body.rtl .cv-mode-card:hover .cv-mode-arrow{ transform:translateX(-4px); }
body.dark-mode .cv-mode-arrow{ background:rgba(255,255,255,.08); color:#7ab8cc; }
body.dark-mode .cv-mode-card:hover .cv-mode-arrow{ background:#0f6b8e; color:#fff; }

/* ── Close button ── */
.cv-mode-modal > .cv-close{
  position:absolute; top:.9rem; right:.9rem; z-index:10;
  background:rgba(255,255,255,.2);
  backdrop-filter:blur(10px);
  border:1px solid rgba(255,255,255,.25);
  color:#fff;
  width:32px; height:32px; border-radius:50%; font-size:.75rem;
  cursor:pointer;
  display:flex; align-items:center; justify-content:center;
  transition:all .2s ease;
}
.cv-mode-modal > .cv-close:hover{
  background:rgba(255,255,255,.32);
  transform:scale(1.1);
}
body.rtl .cv-mode-modal > .cv-close{ right:auto; left:.9rem; }

/* Icon FA icons sizing */
.cv-mode-card .cv-mode-icon i{ font-size:1.3rem; }
.cv-mode-card:nth-child(1) .cv-mode-icon i{ color:#6557e0; }
.cv-mode-card:nth-child(2) .cv-mode-icon i{ color:#3d7a1f; }
.cv-mode-card:nth-child(3) .cv-mode-icon i{ color:#0670a0; }
body.dark-mode .cv-mode-card:nth-child(1) .cv-mode-icon i{ color:#a89cf5; }
body.dark-mode .cv-mode-card:nth-child(2) .cv-mode-icon i{ color:#76b84f; }
body.dark-mode .cv-mode-card:nth-child(3) .cv-mode-icon i{ color:#3ab5e8; }

/* Mobile */
@media (max-width:480px){
  .cv-mode-modal{ border-radius:26px; }
  .cv-mode-top{ padding:1.6rem 1.3rem 1.3rem; }
  .cv-mode-modal h2{ font-size:1.35rem; }
  .cv-mode-options{ padding:1rem .95rem 1.1rem; gap:.45rem; }
  .cv-mode-card{ grid-template-columns:48px 1fr 32px; padding:.85rem .85rem; gap:.7rem; }
  .cv-mode-card .cv-mode-icon{ width:48px; height:48px; border-radius:14px; font-size:1.3rem; }
  .cv-mode-arrow{ width:32px; height:32px; }
}

/* ════════════════════════════════
   DASHBOARD VIEW — MODERN USER
════════════════════════════════ */
#dashboardView .booking-card{
  max-width:1100px;
  margin:0 auto;
  border-radius:30px;
  padding:1.4rem;
  background:linear-gradient(180deg, rgba(255,255,255,.96), rgba(255,255,255,.94));
  box-shadow:0 28px 54px -28px var(--shadow-color);
}
body.dark-mode #dashboardView .booking-card{
  background:linear-gradient(180deg, rgba(15,34,48,.96), rgba(15,34,48,.94));
}
.cv-dash-shell{display:flex;flex-direction:column;gap:1.15rem;}
.cv-dash-hero{
  position:relative;
  overflow:hidden;
  border-radius:32px;
  padding:1.7rem;
  background:
    radial-gradient(circle at top right, rgba(255,255,255,.22), transparent 34%),
    linear-gradient(135deg, #0d4f68 0%, #11718d 52%, #76b84f 100%);
  color:#fff;
  display:grid;
  grid-template-columns:1.3fr .9fr;
  gap:1rem;
  box-shadow:0 28px 50px -24px rgba(15,88,115,.42);
}
.cv-dash-hero::before,
.cv-dash-hero::after{
  content:'';
  position:absolute;
  border-radius:50%;
  pointer-events:none;
}
.cv-dash-hero::before{
  width:180px;height:180px;
  left:-70px;top:-60px;
  background:rgba(255,255,255,.07);
}
.cv-dash-hero::after{
  width:240px;height:240px;
  right:-55px;bottom:-80px;
  background:rgba(255,255,255,.08);
}
.cv-dash-hero > *{position:relative;z-index:1;}
.cv-dash-kicker{
  display:inline-flex;align-items:center;gap:.45rem;
  padding:.42rem .82rem;
  border-radius:999px;
  margin-bottom:.85rem;
  background:rgba(255,255,255,.14);
  border:1px solid rgba(255,255,255,.18);
  font-size:.78rem;
  font-weight:800;
  letter-spacing:.02em;
}
.cv-dash-hero h2{margin:0 0 .4rem;font-size:1.82rem;font-weight:800;color:#fff;}
.cv-dash-hero p{margin:0;color:rgba(255,255,255,.92);max-width:620px;line-height:1.6;}
.cv-dash-hero-actions{display:flex;gap:.7rem;flex-wrap:wrap;margin-top:1.1rem;}
.cv-dash-btn,.cv-dash-btn-secondary{
  border:none;
  border-radius:999px;
  padding:.84rem 1.14rem;
  font-weight:800;
  cursor:pointer;
  display:inline-flex;
  align-items:center;
  gap:.55rem;
  transition:.22s ease;
}
.cv-dash-btn{background:#fff;color:#0f5873;box-shadow:0 14px 26px -16px rgba(0,0,0,.36);}
.cv-dash-btn:hover,.cv-dash-btn-secondary:hover{transform:translateY(-2px);}
.cv-dash-btn-secondary{background:rgba(255,255,255,.14);color:#fff;border:1px solid rgba(255,255,255,.2);}
.cv-dash-profile-card{
  background:rgba(255,255,255,.12);
  border:1px solid rgba(255,255,255,.18);
  border-radius:26px;
  padding:1rem;
  backdrop-filter:blur(10px);
  box-shadow:inset 0 1px 0 rgba(255,255,255,.06);
}
.cv-dash-user-row{display:flex;align-items:center;gap:.85rem;margin-bottom:.9rem;}
.cv-dash-avatar{
  width:62px;height:62px;border-radius:18px;
  display:flex;align-items:center;justify-content:center;
  font-weight:800;font-size:1.05rem;
  background:linear-gradient(180deg, rgba(255,255,255,.22), rgba(255,255,255,.08));
  border:1px solid rgba(255,255,255,.22);
  box-shadow:0 12px 24px -18px rgba(0,0,0,.35);
  overflow:hidden;
  flex-shrink:0;
}
.cv-dash-avatar img{
  width:100%;height:100%;
  object-fit:cover;
  display:block;
}
.cv-dash-user-meta strong{display:block;font-size:1.05rem;}
.cv-dash-user-meta span{font-size:.88rem;opacity:.92;}
.cv-dash-badge{
  display:inline-flex;align-items:center;gap:.38rem;
  margin-top:.28rem;
  padding:.28rem .56rem;
  border-radius:999px;
  background:rgba(255,255,255,.13);
  border:1px solid rgba(255,255,255,.14);
  font-size:.72rem;font-weight:800;
}
.cv-dash-mini{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:.75rem;}
.cv-mini-box{background:rgba(255,255,255,.1);border:1px solid rgba(255,255,255,.14);border-radius:18px;padding:.85rem;}
.cv-mini-box small{display:block;opacity:.84;margin-bottom:.3rem;}
.cv-mini-box strong{font-size:1.1rem;}
.cv-dash-stats{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:1rem;}
.cv-stat-card{
  background:linear-gradient(180deg, rgba(255,255,255,.98), rgba(255,255,255,.92));
  border:1px solid var(--border-color);
  border-radius:24px;
  padding:1rem;
  box-shadow:0 18px 36px -26px var(--shadow-color);
}
body.dark-mode .cv-stat-card{
  background:linear-gradient(180deg, rgba(15,34,48,.98), rgba(15,34,48,.92));
}
.cv-stat-top{display:flex;align-items:center;justify-content:space-between;margin-bottom:.68rem;}
.cv-stat-icon{
  width:44px;height:44px;border-radius:15px;
  display:flex;align-items:center;justify-content:center;
  background:linear-gradient(180deg, var(--accent-light), rgba(118,184,79,.12));color:var(--accent-dark);
}
.cv-stat-card small{display:block;opacity:.72;margin-bottom:.2rem;font-weight:700;}
.cv-stat-card strong{font-size:1.42rem;color:var(--accent-dark);}
.cv-dash-grid{display:grid;grid-template-columns:1.2fr .8fr;gap:1rem;}
.cv-dash-panel{
  background:linear-gradient(180deg, rgba(255,255,255,.98), rgba(255,255,255,.94));
  border:1px solid var(--border-color);
  border-radius:26px;
  padding:1.15rem;
  box-shadow:0 20px 40px -28px var(--shadow-color);
}
body.dark-mode .cv-dash-panel{
  background:linear-gradient(180deg, rgba(15,34,48,.98), rgba(15,34,48,.94));
}
.cv-dash-panel-head{display:flex;align-items:center;justify-content:space-between;gap:1rem;margin-bottom:1rem;}
.cv-dash-panel-head h3{margin:0;color:var(--accent-dark);font-size:1.08rem;}
.cv-dash-panel-head span{font-size:.85rem;opacity:.7;font-weight:700;}
.cv-booking-list{display:flex;flex-direction:column;gap:.95rem;}
.cv-booking-item{
  position:relative;
  border:1px solid var(--border-color);
  border-radius:22px;
  padding:1rem;
  display:grid;
  grid-template-columns:1fr auto;
  gap:.8rem;
  align-items:start;
  background:linear-gradient(180deg, rgba(255,255,255,.88), rgba(255,255,255,.98));
  transition:transform .18s ease, box-shadow .18s ease, border-color .18s ease;
}
.cv-booking-item::before{
  content:'';
  position:absolute;
  top:14px;bottom:14px;left:0;
  width:4px;border-radius:0 999px 999px 0;
  background:linear-gradient(180deg, #0f5873, #76b84f);
}
body.dark-mode .cv-booking-item{
  background:linear-gradient(180deg, rgba(15,34,48,.9), rgba(15,34,48,.98));
}
.cv-booking-item:hover{transform:translateY(-3px);box-shadow:0 18px 30px -24px var(--shadow-color);border-color:rgba(118,184,79,.45);}
.cv-booking-main h4{margin:0 0 .38rem;font-size:1rem;color:var(--accent-dark);}
.cv-booking-meta{display:flex;flex-wrap:wrap;gap:.45rem;margin:.45rem 0 .26rem;}
.cv-booking-pill{display:inline-flex;align-items:center;gap:.35rem;padding:.42rem .68rem;border-radius:999px;background:var(--accent-light);font-size:.78rem;font-weight:700;}
.cv-booking-date{font-size:.82rem;opacity:.68;}
.cv-booking-side{display:flex;flex-direction:column;align-items:flex-end;gap:.55rem;}
.cv-status{padding:.42rem .72rem;border-radius:999px;font-size:.75rem;font-weight:800;border:1px solid transparent;}
.cv-status-pending{background:rgba(237,137,54,.12);color:#c05621;border-color:rgba(237,137,54,.26);}
.cv-status-confirmed{background:rgba(72,187,120,.12);color:#2f855a;border-color:rgba(72,187,120,.25);}
.cv-status-inprogress{background:rgba(66,153,225,.12);color:#2b6cb0;border-color:rgba(66,153,225,.24);}
.cv-status-cancelled{background:rgba(229,62,62,.12);color:#c53030;border-color:rgba(229,62,62,.24);}
.cv-status-completed{background:rgba(56,178,172,.12);color:#285e61;border-color:rgba(56,178,172,.25);}
.cv-empty-dash{text-align:center;padding:2.2rem 1rem;border:1px dashed var(--border-color);border-radius:24px;background:linear-gradient(180deg, var(--accent-light), rgba(118,184,79,.08));opacity:1;}
.cv-empty-dash i{font-size:2rem;color:var(--accent-dark);margin-bottom:.65rem;display:block;}
.cv-profile-list{display:flex;flex-direction:column;gap:.75rem;}
.cv-profile-row{display:flex;justify-content:space-between;gap:1rem;padding:.88rem .95rem;border-radius:18px;background:linear-gradient(180deg, var(--accent-light), rgba(118,184,79,.08));border:1px solid rgba(118,184,79,.1);}
.cv-profile-row span{opacity:.72;font-weight:700;}
.cv-profile-row strong{color:var(--accent-dark);text-align:end;}
.cv-quick-actions{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:.75rem;margin-top:1rem;}
.cv-quick-card{
  border-radius:18px;
  border:1px solid var(--border-color);
  background:var(--card-bg);
  padding:.9rem;
  display:flex;align-items:flex-start;gap:.7rem;
  box-shadow:0 12px 28px -24px var(--shadow-color);
}
.cv-quick-card i{
  width:38px;height:38px;border-radius:12px;
  display:flex;align-items:center;justify-content:center;
  background:var(--accent-light);color:var(--accent-dark);flex-shrink:0;
}
.cv-quick-card strong{display:block;margin-bottom:.2rem;color:var(--accent-dark);font-size:.92rem;}
.cv-quick-card span{display:block;font-size:.8rem;opacity:.72;line-height:1.45;}
@media (max-width:980px){
  .cv-dash-hero,.cv-dash-grid{grid-template-columns:1fr;}
  .cv-dash-stats{grid-template-columns:repeat(2,minmax(0,1fr));}
}
@media (max-width:640px){
  #dashboardView .booking-card{padding:1rem;border-radius:22px;}
  .cv-dash-hero{padding:1.15rem;border-radius:24px;}
  .cv-dash-stats,.cv-quick-actions{grid-template-columns:1fr;}
  .cv-booking-item{grid-template-columns:1fr;padding-left:1.1rem;}
  .cv-booking-side{align-items:flex-start;}
  .cv-profile-row{flex-direction:column;gap:.3rem;}
  .cv-profile-row strong{text-align:start;}
}
/* RTL */
body.rtl .cv-close{right:auto;left:.9rem;}
body.rtl .cv-booking-item{grid-template-columns:auto 1fr;}
body.rtl .cv-err{border-left:none;border-right:3px solid #e53e3e;}
body.rtl .cv-input-icon{left:auto;right:.9rem;}
body.rtl .cv-modal input{padding:.75rem 2.6rem .75rem 1rem;}
body.rtl .cv-user-chip{flex-direction:row-reverse;}

/* ── Booking Action Buttons ── */
.cv-booking-actions{display:flex;gap:.55rem;flex-wrap:wrap;margin-top:.75rem;padding-top:.65rem;border-top:1px solid var(--border-color);}
.cv-action-btn{
  display:inline-flex;align-items:center;gap:.45rem;
  padding:.52rem 1.1rem;border-radius:999px;font-size:.82rem;font-weight:700;
  border:1.5px solid transparent;cursor:pointer;transition:all .18s ease;
  background:none;letter-spacing:.01em;
}
.cv-action-btn:hover{transform:translateY(-1px);box-shadow:0 4px 12px rgba(0,0,0,.1);}
.cv-cancel-btn{color:#c53030;border-color:rgba(229,62,62,.4);background:rgba(229,62,62,.08);}
.cv-cancel-btn:hover{background:rgba(229,62,62,.16);border-color:rgba(229,62,62,.65);}
.cv-rate-btn{color:#276749;border-color:rgba(47,133,90,.4);background:rgba(47,133,90,.08);}
.cv-rate-btn:hover{background:rgba(47,133,90,.16);border-color:rgba(47,133,90,.65);}
.cv-rated-badge{display:inline-flex;align-items:center;gap:.38rem;padding:.42rem .9rem;border-radius:999px;font-size:.78rem;font-weight:700;color:#2f855a;background:rgba(72,187,120,.1);border:1.5px solid rgba(72,187,120,.25);}

/* ── Cancel Confirm Overlay ── */
.cv-cancel-overlay{
  position:fixed;inset:0;z-index:10000;
  background:rgba(0,0,0,.55);backdrop-filter:blur(4px);
  display:flex;align-items:center;justify-content:center;padding:1rem;
}
.cv-cancel-modal{
  background:var(--card-bg);border-radius:28px;padding:2rem;
  max-width:400px;width:100%;
  box-shadow:0 32px 64px -24px rgba(0,0,0,.4);
  animation:fadeInUp .25s ease;text-align:center;
}
.cv-cancel-modal i.big{font-size:2.8rem;color:#e53e3e;margin-bottom:1rem;display:block;}
.cv-cancel-modal h3{margin:0 0 .5rem;color:var(--text-color);}
.cv-cancel-modal p{opacity:.72;font-size:.92rem;margin:0 0 1.4rem;}
.cv-cancel-modal-btns{display:flex;gap:.7rem;justify-content:center;}
.cv-confirm-cancel-btn{background:#e53e3e;color:#fff;border:none;border-radius:999px;padding:.7rem 1.6rem;font-weight:700;font-size:.92rem;cursor:pointer;transition:all .18s;}
.cv-confirm-cancel-btn:hover{background:#c53030;transform:translateY(-1px);}
.cv-keep-btn{background:var(--accent-light);color:var(--accent-dark);border:none;border-radius:999px;padding:.7rem 1.6rem;font-weight:700;font-size:.92rem;cursor:pointer;transition:all .18s;}
.cv-cancel-reason-title{font-weight:600;font-size:.9rem;margin:0 0 .65rem;opacity:.85;text-align:start;}
.cv-cancel-reasons{display:flex;flex-direction:column;gap:.42rem;margin-bottom:.5rem;}
.cv-cancel-reason-option{display:flex;align-items:center;gap:.6rem;padding:.52rem .9rem;border-radius:10px;border:1.5px solid var(--border-color);cursor:pointer;font-size:.87rem;transition:all .15s;text-align:start;}
.cv-cancel-reason-option:has(input:checked){border-color:#e53e3e;background:rgba(229,62,62,.07);}
.cv-cancel-reason-option input[type=radio]{accent-color:#e53e3e;width:15px;height:15px;flex-shrink:0;cursor:pointer;}
.cv-cancel-other-textarea{width:100%;border-radius:10px;border:1.5px solid var(--border-color);padding:.6rem .8rem;font-size:.86rem;background:var(--input-bg);color:var(--text-color);font-family:inherit;resize:vertical;margin-top:.3rem;transition:border .15s;box-sizing:border-box;}
.cv-cancel-other-textarea:focus{outline:none;border-color:#e53e3e;}
.cv-keep-btn:hover{transform:translateY(-1px);}

/* ── Rating Modal ── */
.cv-rating-overlay{
  position:fixed;inset:0;z-index:10000;
  background:rgba(0,0,0,.55);backdrop-filter:blur(4px);
  display:flex;align-items:center;justify-content:center;padding:1rem;
}
.cv-rating-modal{
  background:var(--card-bg);border-radius:28px;padding:2rem;
  max-width:440px;width:100%;
  box-shadow:0 32px 64px -24px rgba(0,0,0,.4);
  animation:fadeInUp .25s ease;
}
.cv-rating-modal h3{margin:0 0 .3rem;color:var(--accent-dark);font-size:1.15rem;}
.cv-rating-modal .cv-rate-sub{opacity:.68;font-size:.88rem;margin:0 0 1.3rem;}
.cv-stars-row{display:flex;gap:.5rem;justify-content:center;margin-bottom:1.1rem;}
.cv-star-btn{
  font-size:2.2rem;cursor:pointer;color:#d1d5db;
  transition:color .15s,transform .15s;background:none;border:none;padding:0;line-height:1;
}
.cv-star-btn.active,.cv-star-btn:hover{color:#f59e0b;transform:scale(1.15);}
.cv-rating-textarea{
  width:100%;border:1.5px solid var(--border-color);border-radius:16px;
  padding:.85rem 1rem;font-size:.92rem;resize:none;min-height:90px;
  background:var(--input-bg);color:var(--text-color);font-family:inherit;
  transition:border-color .2s;box-sizing:border-box;
}
.cv-rating-textarea:focus{outline:none;border-color:var(--accent-dark);}
.cv-rating-modal-btns{display:flex;gap:.7rem;justify-content:flex-end;margin-top:1rem;}
.cv-submit-rating-btn{background:var(--accent-dark);color:#fff;border:none;border-radius:999px;padding:.7rem 1.6rem;font-weight:700;font-size:.92rem;cursor:pointer;transition:all .18s;}
.cv-submit-rating-btn:hover{background:var(--accent-contrast);transform:translateY(-1px);}
.cv-skip-rating-btn{background:var(--accent-light);color:var(--accent-dark);border:none;border-radius:999px;padding:.7rem 1.2rem;font-weight:700;font-size:.92rem;cursor:pointer;}
